 for x in [&f["gross"],&f["net"]]{component(x)?;}
 for name in ["isr","subsidy"]{for x in f[name].as_object().ok_or_else(bad)?.values(){component(x)?;}}
 for name in ["calculated","deducted","absorbedByEmployer","excludedBySimulation"]{component(&f["imss"][name])?;}
