 if xs.iter().all(|x|!x.is_null()){ensure(cents(xs[0])?==cents(xs[1])?.checked_add(cents(xs[2])?).and_then(|n|n.checked_add(cents(xs[3]).ok()?)).ok_or_else(bad)?)?;}
