 for(module,total,parts)in [("imss","calculated",["deducted","absorbedByEmployer","excludedBySimulation"]),("subsidy","determined",["applied","notAppliedDueToNoWithholding","excessOverTariffIsrNotDelivered"])]{if !f[module][total]["amount"].is_null()&&parts.iter().all(|k|!f[module][k]["amount"].is_null()){let mut sum=0_i128;for k in parts{sum=sum.checked_add(cents(&f[module][k]["amount"])?).ok_or_else(bad)?;}ensure(cents(&f[module][total]["amount"])?==sum)?;}}
