fn classification(s:&Value)->&'static str{let r=&s["outcome"]["report"];let p=&s["outcome"]["presentation"];let inv=r["operation"]=="net-to-gross";let f=if inv{&r["recommendedForwardResult"]}else{r};if r["status"]!="estimated"||(inv&&r["match"]=="none"){"not-determinable"}else if !p["confirmation"].is_null()||f["retention"]["kind"]=="conditional-no-withholding-LISR-96"||(inv&&(r["coverage"]["state"]=="fiscally-incomplete"||r["coverage"]["fiscalUnresolvedIntervals"].as_array().map(|a|!a.is_empty()).unwrap_or(false))){"conditioned"}else if inv&&r["coverage"]["state"]=="limited"{"limited"}else if inv&&r["match"]=="exact"{"exact"}else if inv{"approximate"}else{"estimated"}}
